(() => {
 'use strict';
 const $=id=>document.getElementById(id), canvas=$('game'), ctx=canvas.getContext('2d');
 const W=600,H=700,keys=new Set(),stars=Array.from({length:100},()=>({x:Math.random()*W,y:Math.random()*H,s:.5+Math.random()*1.6}));
 let mode='ready',score=0,stage=1,lives=3,best=0,t=0,clock=0,last=0,shot=0,attack=2,transition=0,invincible=0,bullets=[],enemies=[],particles=[],player={x:300,y:640},sound=false,audio;
 try{best=Number(localStorage.getItem('galaxy-best'))||0;}catch{}
 const sprites={player:['000010000','000111000','000111000','010111010','111111111','111111111','110111011','000101000'],bug:['010000010','001000100','011111110','110111011','111111111','101111101','101000101','001000100'],boss:['001000100','011101110','111111111','110111011','111111111','011111110','010101010','110000011']};
 function sprite(type,x,y,color,scale=3){const rows=sprites[type];ctx.fillStyle=color;rows.forEach((r,j)=>{[...r].forEach((v,i)=>{if(v==='1')ctx.fillRect(Math.round(x+(i-4.5)*scale),Math.round(y+(j-4)*scale),scale,scale);});});}
 function beep(freq,duration=.08,type='square'){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,audio.currentTime);o.frequency.exponentialRampToValueAtTime(freq/2,audio.currentTime+duration);g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}catch{}}
 function hud(){$('score').textContent=String(score).padStart(6,'0');$('best').textContent=String(best).padStart(6,'0');$('stage').textContent=String(stage).padStart(2,'0');$('lives').textContent='목숨 '+ '◆ '.repeat(lives);}
 function wave(){enemies=[];for(let r=0;r<4;r++)for(let c=0;c<9;c++)enemies.push({bx:76+c*56,by:100+r*48,x:76+c*56,y:-100-r*48,hp:r===0?2:1,row:r,dive:false,age:0});attack=2;transition=1.6;$('wave').textContent='STAGE '+String(stage).padStart(2,'0');hud();}
 function start(){score=0;stage=1;lives=3;t=0;clock=0;shot=0;invincible=2;bullets=[];particles=[];player.x=300;keys.clear();mode='playing';$('overlay').classList.add('hidden');$('pause').textContent='일시정지';$('overlay').querySelector('h1').textContent='GALAXY';wave();beep(700,.2);}
 function pause(){if(mode==='playing'){mode='paused';$('overlay').classList.remove('hidden');$('overlay').querySelector('h1').textContent='PAUSED';$('message').textContent='잠시 쉬어가세요.';$('start').textContent='계속하기';$('pause').textContent='계속하기';}else if(mode==='paused'){mode='playing';$('overlay').classList.add('hidden');$('pause').textContent='일시정지';}}
 function explode(x,y,color){for(let i=0;i<20;i++){let a=Math.random()*Math.PI*2,s=40+Math.random()*160;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.5+Math.random()*.4,color});}}
 function hit(){if(invincible>0||mode!=='playing')return;lives--;invincible=2.5;explode(player.x,player.y,'#8ee4ff');beep(100,.3,'sawtooth');hud();if(!lives){mode='over';keys.clear();$('overlay').classList.remove('hidden');$('overlay').querySelector('h1').textContent='GAME OVER';$('message').textContent=score.toLocaleString()+'점 · 스테이지 '+stage;$('start').textContent='다시 도전';}}
 function fire(){if(shot<=0&&mode==='playing'&&transition<=0){bullets.push({x:player.x,y:player.y-18,vy:-650,enemy:false});shot=.16;beep(850,.05);}}
 function update(dt){t+=dt;stars.forEach(s=>{s.y+=s.s*dt*24;if(s.y>H)s.y=0;});if(mode!=='playing')return;clock+=dt;shot-=dt;invincible-=dt;transition-=dt;if(transition<=0)$('wave').textContent='';player.x=Math.max(22,Math.min(W-22,player.x+((keys.has('ArrowRight')||keys.has('KeyD')?1:0)-(keys.has('ArrowLeft')||keys.has('KeyA')?1:0))*360*dt));if(keys.has('Space'))fire();
 enemies.forEach(e=>{if(e.dive){e.age+=dt;e.y=e.startY+e.age*(140+stage*14);e.x=e.startX+Math.sin(e.age*3)*95;if(e.y>H+30){e.dive=false;e.y=-30;}}else{e.x=e.bx+Math.sin(clock*1.2)*25;e.y+=(e.by+Math.sin(clock*2+e.bx)*4-e.y)*Math.min(1,dt*3);}if(invincible<=0&&Math.abs(e.x-player.x)<22&&Math.abs(e.y-player.y)<22){e.hp=0;hit();}});
 attack-=dt;if(attack<=0&&transition<=0&&enemies.length){const e=enemies[Math.floor(Math.random()*enemies.length)];if(!e.dive){e.dive=true;e.age=0;e.startX=e.x;e.startY=e.y;}bullets.push({x:e.x,y:e.y+15,vy:200+stage*18,enemy:true,vx:(player.x-e.x)*.25});attack=Math.max(.32,1.25-stage*.08);}
 for(const b of bullets){b.y+=b.vy*dt;b.x+=(b.vx||0)*dt;if(b.enemy){if(Math.abs(b.x-player.x)<13&&Math.abs(b.y-player.y)<18){b.dead=true;hit();}}else{for(const e of enemies)if(e.hp>0&&Math.abs(b.x-e.x)<18&&Math.abs(b.y-e.y)<16){b.dead=true;e.hp--;if(!e.hp){score+=e.dive?200:e.row===0?150:100;explode(e.x,e.y,e.row===0?'#b5f46a':'#ff8499');beep(220,.1);if(score>best){best=score;try{localStorage.setItem('galaxy-best',String(best));}catch{}}hud();}break;}}}
 bullets=bullets.filter(b=>!b.dead&&b.y>-30&&b.y<H+30);enemies=enemies.filter(e=>e.hp>0);particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;});particles=particles.filter(p=>p.life>0);if(!enemies.length&&mode==='playing'){stage++;bullets=[];invincible=2;wave();}}
 function draw(){ctx.fillStyle='#03060e';ctx.fillRect(0,0,W,H);stars.forEach(s=>{ctx.fillStyle=s.s>1.6?'#9fbdd8':'#3a4a65';ctx.fillRect(s.x,s.y,s.s,s.s);});ctx.strokeStyle='#111c30';ctx.beginPath();ctx.moveTo(25,594);ctx.lineTo(575,594);ctx.stroke();if(mode==='ready'){for(let r=0;r<3;r++)for(let c=0;c<7;c++)sprite(r===0?'boss':'bug',132+c*56,105+r*48,r===0?'#b5f46a':r===1?'#ff8499':'#ab95ff');}enemies.forEach(e=>sprite(e.row===0?'boss':'bug',e.x,e.y,e.row===0?(e.hp===1?'#f4d86a':'#b5f46a'):e.row===1?'#ff8499':e.row===2?'#ab95ff':'#6dd9ff'));bullets.forEach(b=>{ctx.fillStyle=b.enemy?'#ff6b87':'#c5ff83';ctx.fillRect(b.x-2,b.y-7,4,b.enemy?12:18);});particles.forEach(p=>{ctx.globalAlpha=Math.min(1,p.life*2);ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,4,4);});ctx.globalAlpha=1;if(mode!=='over'&&(invincible<=0||Math.floor(t*12)%2===0))sprite('player',player.x,player.y,'#8ee4ff',4);}
 function frame(now){const dt=Math.min((now-last)/1000,.033);last=now;update(dt);draw();requestAnimationFrame(frame);}
 $('start').onclick=()=>mode==='paused'?pause():start();$('pause').onclick=pause;$('sound').onclick=()=>{sound=!sound;$('sound').textContent='소리 '+(sound?'ON':'OFF');$('sound').setAttribute('aria-pressed',String(sound));if(sound)beep(600);};
 window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Space','Enter','KeyP'].includes(e.code))e.preventDefault();if(e.repeat)return;if((e.code==='Enter'||e.code==='Space')&&(mode==='ready'||mode==='over')){start();return;}if(e.code==='KeyP'||(e.code==='Enter'&&mode==='paused'))pause();keys.add(e.code);});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(mode==='playing')pause();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&mode==='playing')pause();});
 for(const [id,key] of [['left','ArrowLeft'],['right','ArrowRight'],['fire','Space']]){$(id).addEventListener('pointerdown',e=>{e.preventDefault();$(id).setPointerCapture(e.pointerId);keys.add(key);});for(const type of ['pointerup','pointercancel','lostpointercapture'])$(id).addEventListener(type,()=>keys.delete(key));}
 let dragging=false;function move(e){if(mode==='playing'){const rect=canvas.getBoundingClientRect();player.x=Math.max(22,Math.min(W-22,(e.clientX-rect.left)*W/rect.width));}}canvas.addEventListener('pointerdown',e=>{dragging=true;canvas.setPointerCapture(e.pointerId);move(e);});canvas.addEventListener('pointermove',e=>{if(dragging)move(e);});for(const event of ['pointerup','pointercancel'])canvas.addEventListener(event,()=>dragging=false);
 hud();requestAnimationFrame(frame);
})();
